import{LEVELS,fresh,unlocked,record,finish,recommend,restore,metrics}from'./engine.mjs';
import{CHARACTERS as C,QUESTIONS as Q,DIAGNOSTIC}from'./content.mjs';
import{slidesFor,followingCharacter,resumeIndex}from'./journey.mjs';
import{createPlayer}from'./audio.mjs';
import{QUESTION_BANK}from'./question-bank.mjs';
import{evaluateDraft,recordDraft,draftSummary,latestDraftMistakes,recordStartingCheck}from'./question-engine.mjs';
import{draftQuestionMarkup}from'./draft-views.mjs';
import{TBCL_HANZI}from'./tbcl-hanzi-order.mjs';
const BANK_GROUPS=[...QUESTION_BANK.fullBank,...QUESTION_BANK.worksheetRevisions];
let bank='office',bankLevel='all',bankSearch='',bankMissed=false;

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={profile:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 8 0 0 1 16 0v2',learn:'M4 5h6q2 0 2 2v14q-2-2-8-2Z M20 5h-6q-2 0-2 2v14q2-2 8-2Z',review:'M4 8a8 8 0 1 1-1 7 M4 3v5h5',progress:'M5 20V12 M12 20V5 M19 20V9',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',close:'m6 6 12 12 M6 18 18 6',play:'M4 9h4l5-4v14l-5-4H4Z M17 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',stop:'M7 7h10v10H7Z',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',leaf:'M19 3C3 2 1 15 8 19c7 4 15-3 11-16Z M6 21 17 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`;
let state=fresh(),storageOK=true;
try{const raw=localStorage.getItem('reading-paths-v4-circle-preview');if(raw)state=restore(raw);}catch{storageOK=false;}
if(state.guidedJourneyVersion!==1){if(state.resume){state.resume.index=0;delete state.resume.match;}state.guidedJourneyVersion=1;try{localStorage.setItem('reading-paths-v4-circle-preview',JSON.stringify(state));}catch{storageOK=false;}}
let filter='all',search='',lessonIndex=0,activeCharacter=null,quiz=null,lessonAnswer=null,lessonMatches={},lessonSelectedWord=null,speechPrompted=false,lessonPairOrder=[];
const shuffleItems=items=>{const copy=items.slice();for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;};
const audioItems=new Map();
const player=createPlayer({onState:key=>{document.querySelectorAll('[data-audio]').forEach(b=>{const playing=b.dataset.audio===key;b.classList.toggle('playing',playing);b.setAttribute('aria-pressed',String(playing));b.innerHTML=icon(playing?'stop':'play')+`<span>${playing?'Stop':'Listen'}</span>`;});},onError:toast,onStarted:key=>{
 if(quiz&&!quiz.answered&&key===`assessment:${quiz.questions[quiz.index]?.id}`){quiz.heard=true;document.querySelectorAll('.draft-answers button').forEach(b=>b.disabled=false);const hint=$('#listening-hint');if(hint)hint.textContent='Audio started. Choose what you heard.';}
}});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function applyPrefs(){document.documentElement.dataset.size=state.preferences.size;document.documentElement.dataset.motion=state.preferences.motion;}
function save(){try{localStorage.setItem('reading-paths-v4-circle-preview',JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Progress stays on this device, but this browser could not save it.');}applyPrefs();}
applyPrefs();
const phon=r=>state.preferences.notation==='none'?'':state.preferences.notation==='both'?`${esc(r.pinyin)}<span class="zhuyin">${esc(r.zhuyin)}</span>`:esc(r[state.preferences.notation]);
const choicePhon=r=>state.preferences.notation==='none'?esc(r.pinyin):phon(r);
const questions=id=>Q.filter(q=>q.characterId===id);
const mode=()=>state.learningMode==='explore'?'explore':'guided';
const outstanding=()=>Object.values(state.mistakes).filter(m=>m.correctStreak<2);
const route=()=>location.hash.slice(1).split('/').filter(Boolean);
const pct=n=>n===null?'—':`${Math.round(n)}%`;
function go(path){player.stop();if(location.hash===`#/${path}`)render();else location.hash=`/${path}`;}
function nextAvailable(){const resume=C.find(c=>c.id===state.resume?.characterId);if(resume&&(mode()==='explore'||unlocked(state,resume.level))&&!state.lessons[resume.id]?.passed&&(state.resume.index<slidesFor(resume).length||questions(resume.id).length))return resume;return C.find(c=>c.level===state.start&&(mode()==='explore'||unlocked(state,c.level))&&(questions(c.id).length?!state.lessons[c.id]?.passed:!state.viewed?.[c.id]))||C.find(c=>(mode()==='explore'||unlocked(state,c.level))&&(questions(c.id).length?!state.lessons[c.id]?.passed:!state.viewed?.[c.id]))||C.find(c=>mode()==='explore'||unlocked(state,c.level))||C[0];}
function playButton(item,label){audioItems.set(item.key,item);return`<button class="listen" data-audio="${esc(item.key)}" aria-label="Play ${esc(label||item.text)} in Taiwan Mandarin" aria-pressed="false">${icon('play')}<span>${label?`Listen to ${esc(label)}`:'Listen'}</span></button>`;}
const readingAudio=(c,r)=>{const cue=r.words.find(w=>w.text.length>1);return playButton({key:`reading:${r.id}`,text:c.char,kind:'character',cue},cue?.text||`${c.char}, ${r.pinyin}`)+`<small class="audio-cue">${cue?`Example word: <span lang="zh-Hant">${esc(cue.text)}</span>`:'Clean recording pending'}</small>`;};
const wordAudio=(r,w)=>playButton({key:`word:${r.id}:${w.text}`,text:w.text,kind:'word'},w.text);
const sentenceAudio=s=>playButton({key:`sentence:${s.source.textId}:${s.target}`,text:s.text,kind:'sentence'},'this sentence');

function shell(body,{active='learn',session=false,dock='',title='',welcome=false}={}){
 audioItems.forEach((_,key)=>{if(audioItems.size>300)audioItems.delete(key);});document.body.dataset.session=String(session||welcome);
 const nav=welcome?'':`<nav class="bottom-nav" aria-label="Main navigation">${[['learn','Learn','home'],['review','Review','review'],['progress','Progress','progress'],['profile','Profile','profile']].map(([id,label,path])=>`<a href="#/${path}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('')}</nav>`;
 $('#app').innerHTML=`<div class="app-frame ${welcome?'welcome-frame':''}"><header class="app-header">${session?`<button class="icon-btn" data-action="leave-session" aria-label="Leave check">${icon('close')}</button><span class="session-title">${esc(title)}</span>`:welcome?'<span class="brand brand-welcome">One Character, Many Sounds</span>':'<a class="brand" href="#/home"><span class="brand-mark">✳</span><span>One Character, Many Sounds<small>一字多音</small></span></a>'}${welcome?'':`<button class="icon-btn" data-action="settings" aria-label="Display and audio settings">${icon('settings')}</button>`}</header><main id="main" tabindex="-1" class="${session?'session-main':'page-main'}">${body}</main>${session?dock:nav}</div>`;
}
function dock(primary,action,{back='',secondary='',extra=''}={}){return`<div class="session-dock">${back?`<button class="icon-btn back-control" data-action="${back}" aria-label="Previous learning card">${icon('back')}</button>`:''}<button class="btn primary" data-action="${action}" ${extra}>${primary}${icon('arrow')}</button>${secondary}</div>`;}
function intro(){shell(`<section class="intro welcome-screen"><div class="welcome-orbit" aria-hidden="true"><i></i><i></i><i></i><i></i><b></b></div><p class="eyebrow">A new way to hear Chinese</p><h1>${state.name?`Welcome back, ${esc(state.name)}.`:'One Character,<br>Many Sounds.'}</h1><p class="lead">Explore the different sounds of Chinese characters.</p>${state.name?`<button class="btn primary wide" data-action="howto">Continue ${icon('arrow')}</button>`:`<form id="welcome-form"><label class="field"><span>What should I call you?</span><input id="welcome-name" maxlength="40" autocomplete="nickname" required placeholder="Your nickname"></label><button class="btn primary wide">Let’s begin ${icon('arrow')}</button></form>`}<p class="fine-print">A little practice, at your own pace.</p></section>`,{welcome:true});}
function howto(){shell(`<section class="howto-screen"><p class="eyebrow">A quick guide</p><h1>Here’s how we’ll<br>learn together.</h1><div class="howto-card"><h2>What you can do</h2><p>Explore different readings through short questions, words, example sentences and listening practice. Your learning path suggests what to try next.</p></div><div class="howto-card"><h2>Your progress stays here</h2><p>Your nickname and progress are saved in this browser on this device. There is no account, cloud sync or backup transfer.</p></div><div class="howto-card"><h2>About your level check</h2><p>First, answer 20 questions. The result suggests where to begin practicing; it is not an official TBCL certification.</p></div><button class="btn primary wide" data-action="begin-diagnostic">Take my level check ${icon('arrow')}</button></section>`,{welcome:true,title:'A quick guide'});}
function chooseStart(){shell(`<a class="back-link" href="#/home">${icon('back')} Back</a><p class="eyebrow">Your pace, your choice</p><h1>Where would you<br>like to begin?</h1><p class="lead">Choose a stage. Earlier stages stay open, and Free explore is always available.</p><label class="field"><span>Starting stage</span><select id="start-choice">${LEVELS.map(l=>`<option value="${l}" ${state.start===l?'selected':''}>TBCL ${l}</option>`).join('')}</select></label><button class="btn primary wide" data-action="accept-manual">Start learning ${icon('arrow')}</button>`);}
function home(){return state.onboarded?pathPage():intro();}
function collection(){const list=C.filter(c=>(filter==='all'||c.level===filter)&&(!search||`${c.char} ${c.title} ${c.readings.map(r=>r.pinyin).join(' ')}`.toLowerCase().includes(search.toLowerCase())));shell(`<a href="#/home" class="back-link">${icon('back')} Back to learning</a><p class="eyebrow">Free to be curious</p><h1>Choose a character.</h1><p class="lead">${mode()==='guided'?'Follow the guided stages, or switch to Free explore.':'Every sample character is open. Your progress is shared with the guided path.'}</p><div class="mode-switch"><button data-mode="guided" aria-pressed="${mode()==='guided'}">Guided path</button><button data-mode="explore" aria-pressed="${mode()==='explore'}">Free explore</button></div><div class="filters" aria-label="Filter by stage">${['all',...LEVELS].map(l=>`<button class="pill ${filter===l?'active':''}" data-filter="${l}" aria-pressed="${filter===l}">${l==='all'?'All':l}</button>`).join('')}</div><input class="search" id="search" aria-label="Search characters" placeholder="Search character or Pinyin" value="${esc(search)}"><div class="character-grid">${list.map(c=>`<button class="character-card" data-lesson="${c.id}"><span class="card-top">TBCL ${c.level}${state.lessons[c.id]?.passed?icon('check'):mode()==='guided'&&!unlocked(state,c.level)?icon('lock'):''}</span><span class="card-character" lang="zh-Hant">${c.char}</span><span class="phonetics">${c.readings.map(phon).filter(Boolean).join(' / ')}</span><small>${questions(c.id).length?'Sample lesson':'Preview · quiz pending'}</small></button>`).join('')}</div>${!list.length?'<div class="empty"><h2>More lessons are coming.</h2><p>This stage is waiting for reviewed content.</p><button class="btn secondary" data-filter="all">See available characters</button></div>':''}`);}
function pathPage(){const candidates=TBCL_HANZI.characters.filter(c=>String(c.level)===String(state.start)).slice().sort((a,b)=>(Number(b.spokenFrequency)||0)-(Number(a.spokenFrequency)||0)).slice(0,12);const nodes=candidates.map((x,i)=>{const lesson=C.find(c=>c.char===x.character&&String(c.level)===String(x.level));return{...x,index:i,lesson,ready:!!lesson,completed:!!(lesson&&(state.lessons[lesson.id]?.passed||state.viewed?.[lesson.id]))};});const prepared=nodes.filter(n=>n.ready),active=prepared.find(n=>!n.completed)||prepared.at(-1),height=nodes.length*152;let path='';for(let i=0;i<nodes.length-1;i++){const x1=i%2===0?88:312,y1=75+i*152,x2=(i+1)%2===0?88:312,y2=75+(i+1)*152,m=(y1+y2)/2;path+=`${i?' ':''}M ${x1} ${y1} C ${x1} ${m}, ${x2} ${m}, ${x2} ${y2}`;}shell(`<p class="eyebrow">A path made for you, ${esc(state.name)}</p><h1>Let’s take the next step together.</h1><p class="lead">Follow the circles to explore one character at a time.</p><div class="path-level-pill">Character readings · TBCL ${esc(state.start)}<br>Vocabulary & context · TBCL ${esc(state.wordRecommended||state.start)}</div><div class="character-journey" style="height:${height}px"><svg class="journey-line" viewBox="0 0 400 ${height}" preserveAspectRatio="none" aria-hidden="true"><path d="${path}"/></svg>${nodes.map((n,i)=>{const current=n.index===active?.index,canOpen=n.ready&&(n.completed||current);return `<div class="journey-node ${canOpen?'ready':'pending'} ${n.completed?'completed':''} ${current?'current':''} ${i%2?'right':''}" style="--node-y:${75+i*152}px;--node-x:${i%2===0?'22%':'78%'};--delay:${i*.09}s">${canOpen?`<button class="journey-orb" data-lesson="${n.lesson.id}"><span lang="zh-Hant">${esc(n.character)}</span><small>${n.completed?'Revisit':'Next to learn'}</small></button>`:`<div class="journey-orb"><span lang="zh-Hant">${esc(n.character)}</span><small>${n.completed?'Completed':n.ready?'Up next':'Coming up'}</small></div>`}<div class="journey-caption"><b>${n.ready?esc(n.lesson.title):i===0?'Your next connection':'Keep your path growing'}</b><small>${current?'Your next step':n.completed?'You’ve explored this one':'Keep going to unlock this circle'}</small></div></div>`}).join('')}</div><p class="path-note">Each circle opens a short guided experience with listening, meaning, word practice and writing.</p>`,{active:'learn'});}
function stagePage(l){const open=unlocked(state,l),list=C.filter(c=>c.level===l),previous=LEVELS[Math.max(0,LEVELS.indexOf(l)-1)];shell(`<a href="#/path" class="back-link">${icon('back')} Back to your path</a><p class="eyebrow">${open?'A connection at a time':'Guided path · locked'}</p><h1>TBCL ${esc(l)}</h1><p class="lead">${open?'Choose a character, or check what you already know.':'Explore this stage freely, or pass the previous stage review to open it in your guided path.'}</p>${!open?`<button class="btn primary wide" data-action="explore-stage" data-level="${l}">Explore this stage freely ${icon('arrow')}</button>`:''}<div class="character-grid">${list.map(c=>`<button class="character-card" data-lesson="${c.id}"><span class="card-top">TBCL ${c.level}</span><span class="card-character" lang="zh-Hant">${c.char}</span><small>${c.title}</small></button>`).join('')}</div>${!list.length?'<div class="empty"><p>No reviewed sample lessons at this stage yet.</p></div>':''}<button class="btn ${open?'primary':'secondary'} wide" data-action="stage-quiz" data-level="${open?l:previous}">${open?'Try the stage review':'Challenge the previous stage review'} ${icon('arrow')}</button><p class="fine-print">Sample stage reviews use the available sample questions.<br>They do not certify a TBCL level.</p>`);}
function openLesson(id,{restart=false}={}){const c=C.find(c=>c.id===id);if(!c)return;activeCharacter=id;lessonIndex=restart?0:resumeIndex(c,state.resume);lessonAnswer=null;lessonMatches={};lessonSelectedWord=null;speechPrompted=false;lessonPairOrder=[];quiz=null;go('lesson/'+id);}
function lesson(id){const c=C.find(c=>c.id===id);if(!c)return go('home');if(mode()==='guided'&&!unlocked(state,c.level))return stagePage(c.level);if(activeCharacter!==id){activeCharacter=id;lessonIndex=resumeIndex(c,state.resume);lessonAnswer=null;lessonMatches=state.resume?.characterId===id&&state.resume?.index===lessonIndex?(state.resume.match||{}):{};lessonSelectedWord=null;lessonPairOrder=[];}const slides=slidesFor(c);lessonIndex=Math.max(0,Math.min(lessonIndex,slides.length));state.resume={characterId:id,index:lessonIndex,...(slides[lessonIndex]?.kind==='sort'?{match:lessonMatches}:{})};if(lessonIndex===slides.length){state.viewed??={};state.viewed[id]=true;}save();if(lessonIndex===slides.length)return lessonEnd(c);const slide=slides[lessonIndex],r=slide.reading;let content='',heading='Keep going, one step at a time.';if(slide.kind==='intro'){const pair=c.readings.map(x=>phon(x)).join(' · ');heading='Let’s explore this character.';content=`<p class="eyebrow">Welcome to this character</p><div class="focus-character" lang="zh-Hant">${c.char}</div><h1 class="meaning">Let’s explore ${c.char}.</h1><p class="teaching-tip">This character has ${c.readings.length} readings: <b>${pair}</b>. We’ll take them one at a time—listen, notice what each means, and practise the words that use it.</p><div class="reading-pair">${c.readings.map(x=>`<span class="phonetics">${phon(x)}</span>`).join('<span class="divider">·</span>')}</div><p class="fine-print">Take your time. Your voice is not recorded.</p>`;}if(slide.kind==='listen'){heading='First, listen.';const cue=r.words.find(w=>w.text.length>1);content=`<p class="eyebrow">Listen to this reading</p><div class="focus-character" lang="zh-Hant">${c.char}</div><div class="phonetics focus-phonetics">${phon(r)}</div>${readingAudio(c,r)}<h1 class="meaning">Listen to the example word.</h1><p class="teaching-tip">Notice how ${c.char} sounds in this word. Next, you’ll choose the word you heard.</p>`;}if(slide.kind==='audio-choice'){heading='Listen, then choose the word.';const cue=r.words.find(w=>w.text.length>1),choices=c.readings.map(x=>({reading:x,word:x.words.find(w=>w.text.length>1)})),keyAnswer=r.id;content=`<p class="eyebrow">Listen and identify</p><div class="focus-character" lang="zh-Hant">${c.char}</div><p class="teaching-tip">Listen to the audio. Which word did you hear?</p>${playButton({key:`listen-check:${slide.id}`,text:cue.text,kind:'word'},'audio clip')}<div class="answers">${choices.map(x=>`<button class="answer ${lessonAnswer===x.reading.id?(x.reading.id===keyAnswer?'correct':'incorrect'):''}" data-lesson-choice="${x.reading.id}" ${lessonAnswer?'disabled':''}><span>•</span><b lang="zh-Hant">${esc(x.word.text)}</b></button>`).join('')}</div>${lessonAnswer?`<div class="feedback ${lessonAnswer===keyAnswer?'':'wrong'}" role="status"><p>${lessonAnswer===keyAnswer?`That’s ${esc(cue.text)}. ${esc(c.char)} is read ${esc(r.pinyin)} here; the word means ${esc(cue.gloss)}.`:`Listen again: the word was ${esc(cue.text)}. Here ${esc(c.char)} is read ${esc(r.pinyin)}.`}</p></div>`:'<p class="fine-print">Choose the written word you heard. The reading and meaning will appear after your answer.</p>'}`;}if(slide.kind==='meaning'){heading='Now, notice the meaning.';const options=[...new Map(c.readings.map(x=>[x.meaning,x])).values()];content=`<p class="eyebrow">What does this sound mean?</p><div class="focus-character" lang="zh-Hant">${c.char}</div><div class="phonetics focus-phonetics">${phon(r)}</div>${readingAudio(c,r)}<h2 class="guided-question">Which meaning belongs to this reading?</h2><div class="answers">${options.map(x=>`<button class="answer ${lessonAnswer===x.id?(x.id===r.id?'correct':'incorrect'):''}" data-lesson-choice="${esc(x.id)}" ${lessonAnswer?'disabled':''}><span>•</span><b>${esc(x.meaning)}</b></button>`).join('')}</div>${lessonAnswer?`<div class="feedback ${lessonAnswer===r.id?'':'wrong'}" role="status"><p>${lessonAnswer===r.id?'That’s right.':'Let’s remember: this reading means '+esc(r.meaning)+'.'}</p></div>`:'<p class="fine-print">Choose the meaning that matches what you just heard.</p>'}`;}if(slide.kind==='speak'){heading='Say the sound out loud.';const cue=r.words.find(w=>w.text.length>1);content=`<p class="eyebrow">Your turn to speak</p><div class="focus-character" lang="zh-Hant">${c.char}</div><div class="phonetics focus-phonetics">${phon(r)}</div><p class="meaning">Say <b>${esc(r.pinyin)}</b> out loud.</p><p class="teaching-tip">Listen again if you need a model, then say it yourself. This preview doesn’t record or grade your voice.</p><div class="speak-task">${readingAudio(c,r)}<p class="fine-print">Listen again if you want a model, then say the sound yourself.</p>${speechPrompted?`<div class="say-it-prompt" role="status"><span>Now say</span><b>${esc(r.pinyin)}</b><small>Say it out loud. Your voice is not recorded.</small></div><button class="btn secondary wide" data-action="spoken-practised">I said it</button>`:`<button class="btn secondary wide" data-action="start-speaking">Start speaking</button>`}</div>`;}if(slide.kind==='write'){heading='Try writing it.';content=`<p class="eyebrow">Your turn to write</p><h1 class="meaning">Try writing this character from memory.</h1><canvas class="writing-pad" width="360" height="360" aria-label="Practice writing this character"></canvas><button class="text-btn" data-action="clear-writing">Clear and try again</button><details class="quiet-details"><summary>Show the character</summary><div class="writing-model" lang="zh-Hant">${c.char}</div></details><p class="teaching-tip">Take your time. This practice is just for you.</p>`;}if(slide.kind==='vocab-preview'){heading='Meet the words before you match them.';const groups=[r].map(x=>`<section class="vocab-group"><h2>${esc(x.pinyin)} · ${esc(x.meaning)}</h2>${x.words.filter(w=>w.text.length>1).map(w=>`<article class="vocab-preview-item"><div><b lang="zh-Hant">${esc(w.text)}</b><div class="phonetics">${phon(w)}</div><p>${esc(w.gloss)}</p><small>TBCL ${esc(w.level)}</small></div>${wordAudio(x,w)}</article>`).join('')}</section>`).join('');content=`<p class="eyebrow">Look, listen, and notice</p><p class="teaching-tip">Here are a few words that use each sound. Listen to them and read what they mean before the matching game.</p>${groups}`;}if(slide.kind==='sort'){heading='Bring both readings together.';if(!lessonPairOrder.length)lessonPairOrder=shuffleItems(slide.pairs);const pairs=lessonPairOrder;content=`<p class="eyebrow">Final mixed practice</p><h2 class="guided-question">Match each word to the sound of ${esc(c.char)}.</h2><p class="teaching-tip">Start with any word. If you’re unsure, use its speaker button as a listening clue.</p><div class="match-words">${pairs.map(([word,id])=>{const matched=lessonMatches[word]===id;const source=c.readings.find(x=>x.id===id),w=source.words.find(x=>x.text===word);return `<div class="match-word-row"><button class="match-word ${matched?'matched':''} ${lessonSelectedWord===word?'selected':''}" data-match-word="${esc(word)}" ${matched?'disabled':''}>${esc(word)}</button>${wordAudio(source,w)}</div>`}).join('')}</div><div class="match-readings">${c.readings.map(x=>`<button class="answer match-reading" data-match-reading="${x.id}"><span>${esc(c.char)}</span><b>${phon(x)}</b></button>`).join('')}</div>${lessonAnswer?`<div class="feedback ${lessonAnswer==='matched'?'':'wrong'}" role="status"><p>${lessonAnswer==='matched'?'That connection fits. Choose another word.':'Not quite. Listen to the word and try another sound.'}</p></div>`:''}<p class="fine-print">Matched ${Object.keys(lessonMatches).length} of ${pairs.length}. Take your time.</p>`;}if(slide.kind==='word'){heading='Let’s use it in a word.';const w=slide.word,choices=[{key:'correct',label:w.gloss},...c.readings.filter(x=>x.id!==r.id).map(x=>({key:`other:${x.id}`,label:x.meaning}))];content=`<p class="eyebrow">Listen and choose</p><div class="focus-word zh" lang="zh-Hant">${esc(w.text)}</div><div class="phonetics focus-phonetics">${phon(w)}</div>${wordAudio(r,w)}<h2 class="guided-question">What does this word mean?</h2><div class="answers">${choices.map(x=>`<button class="answer ${lessonAnswer===x.key?(x.key==='correct'?'correct':'incorrect'):''}" data-lesson-choice="${esc(x.key)}" ${lessonAnswer?'disabled':''}><span>•</span><b>${esc(x.label)}</b></button>`).join('')}</div>${lessonAnswer?`<div class="feedback ${lessonAnswer==='correct'?'':'wrong'}" role="status"><p>${lessonAnswer==='correct'?'That’s right.':`Here, ${esc(w.text)} means ${esc(w.gloss)}.`}</p></div>`:'<p class="fine-print">Take a moment, then choose the meaning that fits.</p>'}<small class="fine-print">Word level · TBCL ${esc(w.level)}</small>`;}if(slide.kind==='sentence'){heading='Hear it in context.';const sentence=slide.sentence;const sentenceChoices=[{key:'correct',label:r.meaning},...c.readings.filter(x=>x.id!==r.id).map(x=>({key:`other:${x.id}`,label:x.meaning}))];content=`<p class="eyebrow">Listen to the example</p><p class="focus-sentence zh" lang="zh-Hant">${esc(sentence.text).replace(esc(sentence.target),`<mark>${esc(sentence.target)}</mark>`)}</p>${sentenceAudio(sentence)}<h2 class="guided-question">What does the highlighted word mean here?</h2><div class="answers">${sentenceChoices.map(x=>`<button class="answer ${lessonAnswer===x.key?(x.key==='correct'?'correct':'incorrect'):''}" data-lesson-choice="${esc(x.key)}" ${lessonAnswer?'disabled':''}><span>•</span><b>${esc(x.label)}</b></button>`).join('')}</div>${lessonAnswer?`<div class="feedback ${lessonAnswer==='correct'?'':'wrong'}" role="status"><p>${lessonAnswer==='correct'?'That’s right.':`Here, it matches the ${esc(r.meaning)} meaning.`}</p></div>`:'<p class="teaching-tip">Listen, find the highlighted word, and choose the meaning that fits.</p>'}`;}if(slide.kind==='sentence-pending'){heading='Keep exploring.';content=`<p class="eyebrow">One more connection</p><div class="pending-mark" lang="zh-Hant">${c.char}</div><h1 class="meaning">A good example sentence<br>is still being reviewed.</h1><p class="teaching-tip">We’re looking for a natural sentence from the National Academy for Educational Research corpus that clearly shows this reading.</p>`;}const next=slides[lessonIndex+1],label=!next?'Finish this character':next.kind==='listen'?'Learn the other reading':next.kind==='meaning'?'Learn its meaning':next.kind==='speak'?'Say it out loud':next.kind==='write'?'Try writing it':next.kind==='vocab-preview'?'Meet related words':next.kind==='audio-choice'?'Listen and choose':next.kind==='word'?'Practise a word':next.kind==='sentence-pending'?'Sentence practice':next.kind==='sort'?'Mixed review':'Keep going',needsAnswer=['meaning','audio-choice','word','sentence'].includes(slide.kind),extra=(needsAnswer&&!lessonAnswer||slide.kind==='speak'&&!speechPrompted||slide.kind==='sort'&&Object.keys(lessonMatches).length<(slide.pairs?.length||0))?'disabled':'';shell(`<div class="session-progress"><div><span>TBCL ${c.level} · <span lang="zh-Hant">${c.char}</span></span><span>${lessonIndex+1} / ${slides.length}</span></div><div class="progress-track" role="progressbar" aria-label="Learning steps" aria-valuemin="0" aria-valuemax="${slides.length}" aria-valuenow="${lessonIndex+1}"><span style="width:${100*(lessonIndex+1)/slides.length}%"></span></div></div><article class="focus-card guided-card">${content}</article>`,{session:true,title:`Learn ${c.char}`,dock:dock(label,'next-card',{back:lessonIndex?'previous-card':'',extra})});}
function nextFor(c){return followingCharacter(C,c.id,state,mode(),unlocked);}
function continuation(c){return{label:'Back to your character path',action:'back-to-path',extra:''};}
function lessonEnd(c){const ready=questions(c.id).length,next=continuation(c);shell(`<section class="result-card"><span class="result-mark">${icon('check')}</span><p class="eyebrow">Character explored</p><h1>One character.<br>More connections.</h1><div class="end-readings">${c.readings.map(r=>`<div><span class="end-character" lang="zh-Hant">${c.char}</span><span><b>${phon(r)||'Reading explored'}</b><small>${esc(r.meaning)}</small></span>${readingAudio(c,r)}</div>`).join('')}</div><p class="lead">${ready?'Try five short questions to check these reading connections.':'The check for this character is still being prepared. You can continue learning.'}</p><button class="text-btn" data-action="restart-character" data-id="${c.id}">Explore this character again</button></section>`,{session:true,title:'Learning · Character complete',dock:ready?dock('Try the 5-question check','lesson-quiz',{extra:`data-id="${c.id}"`}):dock(next.label,next.action,{extra:next.extra,back:'previous-card'})});}
function startQuiz(type,id){let qs=type==='diagnostic'?QUESTION_BANK.startingCheck:type==='team'?(BANK_GROUPS.find(g=>g.id===id)?.questions||[]):type==='lesson'?questions(id):type==='stage'?Q.filter(q=>C.find(c=>c.id===q.characterId).level===id):id?[Q.find(q=>q.id===id)].filter(Boolean):outstanding().filter(m=>m.due<=Date.now()).map(m=>Q.find(q=>q.id===m.questionId)).filter(Boolean);if(!qs.length){toast(type==='stage'?'This stage review is waiting for reviewed questions.':'No review questions are due right now.');return;}player.stop();quiz={type,id,questions:qs,index:0,score:0,answered:false,chosen:null,done:false,outcomes:[],heard:false,previewed:false,matchAnswers:{}};go('quiz');}
function quizPage(){if(!quiz)return go(state.onboarded?'home':'start');if(quiz.done)return result();if(quiz.questions[quiz.index].rawText)return draftQuizPage();const t=quiz,q=t.questions[t.index],c=C.find(c=>c.id===q.characterId);shell(`<div class="session-progress"><div><span>${t.type==='diagnostic'?'Starting check':t.type==='stage'?`Stage ${t.id} review`:t.type==='review'?'Review':`${c.char} · Character check`}</span><span>${t.index+1} / ${t.questions.length}</span></div><div class="progress-track" role="progressbar" aria-label="Check progress" aria-valuemin="0" aria-valuemax="${t.questions.length}" aria-valuenow="${t.index+1}"><span style="width:${100*(t.index+1)/t.questions.length}%"></span></div></div><section class="question-card"><p class="eyebrow">Choose a reading</p><h1 class="question-heading">How is <span lang="zh-Hant">${c.char}</span><br>read in this word?</h1><div class="quiz-word zh" lang="zh-Hant">${esc(q.word)}</div><div class="answers">${c.readings.map((r,i)=>`<button class="answer ${t.answered&&t.type==='diagnostic'&&r.id===t.chosen?'selected':t.answered&&r.id===q.readingId?'correct':t.answered&&r.id===t.chosen?'incorrect':''}" data-answer="${r.id}" ${t.answered?'disabled':''}><span>${String.fromCharCode(65+i)}</span><b>${choicePhon(r)}</b>${t.type!=='diagnostic'&&t.answered&&r.id===q.readingId?icon('check'):''}</button>`).join('')}</div>${t.answered?(t.type==='diagnostic'?'<div class="feedback" role="status"><p>Your response is saved. Let’s continue.</p></div>':`<div class="feedback ${t.chosen===q.readingId?'':'wrong'}" role="status"><h2>${t.chosen===q.readingId?'That connection fits.':'A useful one to revisit.'}</h2><p>${esc(q.explanation)} ${t.chosen!==q.readingId?'Saved in Review.':''}</p></div>`):'<p class="fine-print">Take your time. Choose one answer.</p>'}${state.preferences.notation==='none'?'<p class="fine-print">Reading choices stay visible during pronunciation questions.</p>':''}</section>`,{session:true,title:t.type==='diagnostic'?'Find your starting point':'Check your connection',dock:t.answered?dock(t.index+1===t.questions.length?'See your result':'Next question','next-question'):'<div class="session-dock"><p class="dock-hint">Choose an answer to continue.</p></div>'});if(t.answered)document.querySelector('.session-dock .btn')?.focus({preventScroll:true});}
function result(){if(['diagnostic','team'].includes(quiz.type))return draftResult();const t=quiz,pass=t.score/t.questions.length>=.8;if(t.type==='diagnostic'){const l=recommend(t.score,t.questions.length);shell(`<section class="result-card"><p class="eyebrow">A starting suggestion</p><h1>Start where<br>it feels right.</h1><div class="result-score">${l}</div><h2>Suggested stage · TBCL ${l}</h2><p class="lead">${t.score} of ${t.questions.length} sample questions correct. This suggests where to begin these lessons; it is not a TBCL proficiency result.</p><label class="field"><span>Your starting stage</span><select id="result-start">${LEVELS.map(x=>`<option value="${x}" ${x===l?'selected':''}>TBCL ${x}</option>`).join('')}</select></label><p class="fine-print">Choose a different stage if you prefer.<br>You can change it later.</p></section>`,{session:true,title:'Your starting point',dock:dock('See your learning path','accept-start')});return;}
 const c=t.type==='lesson'?C.find(c=>c.id===t.id):null,next=c?continuation(c):null;
 let action='result-home',label='Back to learning',extra='';if(c&&pass){({label,action,extra}=next);}else if(c){action='restart-character';label=`Relearn ${c.char}`;extra=`data-id="${c.id}"`;}else if(t.type==='stage'&&pass){const nextStage=LEVELS[LEVELS.indexOf(t.id)+1],first=C.find(c=>c.level===nextStage);if(first){action='next-character';label=`Next character: ${first.char}`;extra=`data-id="${first.id}"`;}}
 shell(`<section class="result-card"><span class="result-mark">${icon(pass?'check':'review')}</span><p class="eyebrow">${t.type==='review'?'Review saved':pass?'A step forward':'Progress includes coming back'}</p><h1>${t.type==='review'?'Keep the connection<br>growing.':pass?'Nicely connected.':'Let’s revisit<br>a few.'}</h1><div class="result-score">${t.score}<small> / ${t.questions.length}</small></div><p class="lead">${t.type==='review'?'One correct revisit schedules the next for tomorrow. Two correct answers move an item out of active review.':t.type==='stage'?(pass?'Stage review passed. The next stage is now open.':'Aim for 80% to pass. Your missed connections are saved in Review.'):(pass?'Character check passed. Your progress is shared with Free explore and the guided path.':'Aim for 4 out of 5 to pass. Your missed connections are saved in Review.')}</p><a class="text-btn" href="#/review">${outstanding().length?'Revisit missed connections':'Open your review space'}</a>${t.type!=='review'?'<button class="text-btn" data-action="retry">Try this check again</button>':''}</section>`,{session:true,title:'Your result',dock:dock(label,action,{extra})});}
function review(){const items=Object.values(state.mistakes).sort((a,b)=>a.due-b.due),due=items.filter(m=>m.correctStreak<2&&m.due<=Date.now());shell(`<p class="eyebrow">Your review space</p><h1>A fresh look.<br>A stronger connection.</h1><p class="lead">Come back to the exact word and reading that needs practice.</p><a class="link-row" href="#/team"><span>Team draft review<small>${latestDraftMistakes(state).length} missed draft items · separate from learning review</small></span>${icon('arrow')}</a>${items.length?`<button class="btn primary wide" data-action="review-quiz" ${!due.length?'disabled':''}>${due.length?`Review ${due.length} due connection${due.length===1?'':'s'}`:'You’re up to date'} ${icon('arrow')}</button><div class="review-list">${items.map(m=>{const q=Q.find(q=>q.id===m.questionId);if(!q)return'';const c=C.find(c=>c.id===q.characterId),r=c.readings.find(r=>r.id===q.readingId);const w=r.words.find(w=>q.word.startsWith(w.text));return`<article class="review-item"><div class="review-word"><div><p class="zh" lang="zh-Hant">${esc(q.word)}</p><div class="phonetics">${phon(r)}</div></div>${w?wordAudio(r,w):''}</div><p class="fine-print">${m.wrongCount} missed attempt${m.wrongCount===1?'':'s'} · ${m.correctStreak>=2?'Revisited twice':m.due>Date.now()?`Next revisit ${new Date(m.due).toLocaleDateString('en-US',{month:'short',day:'numeric'})}`:'Ready to revisit'}</p><div class="split-buttons"><button class="btn secondary" data-relearn="${c.id}">Relearn</button><button class="btn secondary" data-review-id="${q.id}">Practise ${icon('arrow')}</button></div></article>`;}).join('')}</div><details class="quiet-details"><summary>How review works</summary><p>Wrong answers are saved by character, reading and word. One correct revisit schedules another for tomorrow; two correct answers move it out of active review. This sample repeats the original question, so the record indicates practice rather than validated mastery.</p></details>`:'<div class="empty"><span class="result-mark">'+icon('review')+'</span><h2>A clear space for now.</h2><p>Words you miss in a check will appear here, ready to revisit.</p><a class="btn primary" href="#/home">Keep learning '+icon('arrow')+'</a></div>'}`,{active:'review'});}
function progress(){const m=metrics(state),completed=Object.values(state.lessons).filter(l=>l.passed).length;shell(`<p class="eyebrow">Your progress</p><h1>See your connections<br>grow.</h1><div class="metric-grid"><article><strong>${pct(m.accuracy)}</strong><h2>Overall accuracy</h2><p>${m.answerCount} practice answers<br>Includes repeat answers</p></article><article><strong>${pct(m.quizAverage)}</strong><h2>Average quiz score</h2><p>${m.quizCount} completed character quizzes<br>Includes retakes</p></article></div><details class="quiet-details"><summary>What these numbers mean</summary><p>Overall accuracy = correct practice answers ÷ all practice answers. Average quiz score = the mean percentage of your completed character quizzes. Stage reviews, starting checks and review sessions are excluded from that quiz average. Starting checks are excluded from both metrics.</p><p>First-attempt accuracy: <b>${pct(m.firstAccuracy)}</b> across ${m.firstCount} different questions. It counts each question’s first practice answer once.</p>${!m.quizCount&&Object.keys(state.lessons).length?'<p>Earlier best scores are preserved below. Average quiz score starts with newly recorded quizzes.</p>':''}</details><div class="progress-summary"><span><b>${completed}</b> character checks passed</span><span><b>${state.stagePasses.length}</b> stage reviews passed</span></div><h2 class="section-title">Your characters</h2><div class="score-list">${C.map(c=>{const qs=state.attempts.filter(a=>a.characterId===c.id&&a.mode!=='diagnostic'),l=state.lessons[c.id];return`<div><span class="score-char" lang="zh-Hant">${c.char}</span><span><b>${l?`Best ${l.best}/${l.total}`:'No quiz completed'}</b><small>${qs.length?`${Math.round(100*qs.filter(a=>a.correct).length/qs.length)}% correct · ${qs.length} answers`:'Not practised yet'}</small></span>${l?.passed?icon('check'):''}</div>`;}).join('')}</div><a class="link-row" href="#/team"><span>Team draft activity<small>${state.teamAttempts.length} responses · separate from learning scores</small></span>${icon('arrow')}</a>`,{active:'progress'});}
function settings(){const d=$('#settings');d.className='settings-dialog';d.innerHTML=`<div class="dialog-heading"><h2 id="settings-title">Make it comfortable.</h2><button class="icon-btn" data-action="close-settings" aria-label="Close settings">${icon('close')}</button></div><fieldset><legend>Text size</legend><div class="choice-row">${['small','medium','large'].map(x=>`<button class="pill" data-pref="size" data-value="${x}" aria-pressed="${state.preferences.size===x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></fieldset><fieldset><legend>Pronunciation hints</legend><div class="choice-row">${[['pinyin','Pinyin'],['zhuyin','Zhuyin 注音'],['both','Both'],['none','Hide']].map(([x,label])=>`<button class="pill" data-pref="notation" data-value="${x}" aria-pressed="${state.preferences.notation===x}">${label}</button>`).join('')}</div></fieldset><fieldset><legend>Playback speed</legend><div class="choice-row">${[['normal','Normal'],['slow','Slow']].map(([x,label])=>`<button class="pill" data-pref="speed" data-value="${x}" aria-pressed="${state.preferences.speed===x}">${label}</button>`).join('')}</div></fieldset>><div class="settings-preview"><span class="zh" lang="zh-Hant">快樂</span><div class="phonetics">${phon(C[2].readings[0].words[0])}</div>${wordAudio(C[2].readings[0],C[2].readings[0].words[0])}</div><details class="quiet-details"><summary>About Taiwan Mandarin audio</summary><p>Playback uses a Taiwan Mandarin voice available on your device, at no service charge from this tool. Character buttons play the visible word example. Isolated readings without a clean recording remain pending. Device speech still needs pronunciation review.</p><a href="#/profile" data-action="audio-setup">Open Profile → Audio setup</a><p>Archived dictionary source and original licence (excluded from learner playback): <a href="./audio/README.md" target="_blank" rel="noopener">audio sources</a> · <a href="./audio/LICENSE-MOE.pdf" target="_blank" rel="noopener">MOE terms</a>.</p></details><button class="btn primary wide" data-action="close-settings">Done</button>`;if(!d.open)d.showModal();}
function draftQuizPage(){
 const t=quiz,q=t.questions[t.index];
 shell(`<div class="session-progress"><div><span>${t.type==='diagnostic'?'Starting check':`${esc(q.character)} · Team preview`}</span><span>${t.index+1} / ${t.questions.length}</span></div><div class="progress-track" role="progressbar" aria-label="Draft check progress" aria-valuemin="0" aria-valuemax="${t.questions.length}" aria-valuenow="${t.index+1}"><span style="width:${100*(t.index+1)/t.questions.length}%"></span></div></div><section class="question-card">${draftQuestionMarkup(q,t,{play:playButton,icon})}</section>`,{session:true,title:t.type==='diagnostic'?'Find a starting point':'Team question preview',dock:t.answered?dock(t.index+1===t.questions.length?'See draft result':'Next question','next-question'):'<div class="session-dock"><p class="dock-hint">Explore the prompt, then choose a response.</p></div>'});
 if(t.answered)document.querySelector('.session-dock .btn')?.focus({preventScroll:true});
}
function submitDraft(response,{preview=false}={}){
 if(!quiz||quiz.answered)return;const q=quiz.questions[quiz.index];player.stop();
 quiz.previewed ||= preview;const outcome=evaluateDraft(q,response,quiz);quiz.chosen=typeof response==='string'?response:null;quiz.answered=true;quiz.outcomes.push(outcome);
 if(outcome.correct)quiz.score++;if(quiz.type==='team'){state=recordDraft(state,q,response,outcome);save();}draftQuizPage();
}
function draftResult(){const t=quiz,m=draftSummary(t.outcomes),diagnostic=t.type==='diagnostic';if(!diagnostic){shell(`<section class="result-card"><span class="status-chip">Team draft · unvalidated</span><p class="eyebrow">Worksheet preview complete</p><h1>Thanks for trying<br>the draft.</h1><div class="result-score">${m.correct}<small> / ${m.scored} scored</small></div><p class="lead">${m.total} questions explored · ${m.unscored} unscored.</p><button class="text-btn" data-action="retry">Try this set again</button></section>`,{session:true,title:'Draft result',dock:dock('Back to question bank','team-home')});return;}const a=draftSummary(t.outcomes.slice(0,10)),b=draftSummary(t.outcomes.slice(10,20)),lvl=x=>x.unscored?state.start:x.correct/x.scored>=.8?'2':x.correct/x.scored>=.5?'1*':'1',ca=lvl(a),wo=lvl(b),desc=l=>({'1':'You can explore familiar, everyday words and short phrases.','1*':'You are ready to try more challenging words in this level.','2':'You can explore short sentences and everyday conversations.'})[l]||'You are ready to try more challenging words in this level.';shell(`<section class="result-card placement-result"><div class="result-orbit" aria-hidden="true"><i></i><i></i><i></i></div><p class="eyebrow">Your suggested starting points</p><h1>Here’s where<br>we can begin.</h1><div class="placement-grid"><article><span>Character readings</span><strong>TBCL ${ca}</strong><p>${desc(ca)}</p></article><article><span>Vocabulary & context</span><strong>TBCL ${wo}</strong><p>${desc(wo)}</p></article></div><details class="quiet-details"><summary>What does TBCL mean?</summary><p>TBCL is Taiwan’s official framework for describing Chinese proficiency. A star means more challenging items within the same level.</p><a href="https://coct.naer.edu.tw/page.jsp?ID=11" target="_blank" rel="noopener">Official level descriptions ↗</a></details><p class="fine-print">These are practice suggestions from this 20-question prototype, not a proficiency result.</p></section>`,{session:true,title:'Your starting points',dock:dock('See your learning path','accept-start')});}
function profile(){shell(`<p class="eyebrow">Your learning profile</p><h1>Hi, ${esc(state.name)}.</h1><section class="profile-check"><h2>Your suggested starting points</h2><p>Character readings · TBCL ${esc(state.start)}<br>Vocabulary and context · TBCL ${esc(state.wordRecommended||state.start)}</p><button class="btn primary wide" data-action="diagnostic">Retake level check ${icon('arrow')}</button><small>20 questions · no timer · practice suggestions only</small></section><form id="profile-form"><label class="field"><span>What should I call you?</span><input id="learner-name" value="${esc(state.name)}" maxlength="40" autocomplete="nickname" required></label><button class="btn secondary wide" type="submit">Save nickname</button></form><button class="link-row" data-action="settings"><span>Display & playback<small>Text size, pronunciation hints and speed</small></span>${icon('settings')}</button><p class="fine-print">Your progress is saved in this browser on this device. There is no account or cloud sync.</p>`,{active:'profile'});}
function teamLibrary(){
 const missed=new Set(latestDraftMistakes(state).map(a=>a.questionId));
 const list=BANK_GROUPS.filter(g=>g.bank===bank&&(bankLevel==='all'||g.level===bankLevel)&&(!bankSearch||g.character.includes(bankSearch))&&(!bankMissed||g.questions.some(q=>missed.has(q.id))));
 shell(`<a class="back-link" href="#/home">${icon('back')} Back to learning</a><p class="eyebrow">For team testing</p><h1>Explore the<br>draft questions.</h1><p class="draft-notice">All 64 source character sets are available here. This includes disputed readings and material outside the final course scope. Results stay separate from learning scores and stage unlocks.</p><div class="mode-switch"><button data-bank="office" aria-pressed="${bank==='office'}">Original · 320</button><button data-bank="revisions" aria-pressed="${bank==='revisions'}">Revisions · 15</button></div><p class="fine-print">The revisions for 中、好、行 are kept as a separate source version. Team-authored question text is not a COCT quotation.</p><div class="team-filters"><label class="field"><span>Source character stage</span><select id="bank-level"><option value="all">All stages</option>${[...new Set(BANK_GROUPS.map(g=>g.level))].map(l=>`<option value="${esc(l)}" ${bankLevel===l?'selected':''}>${esc(l)}</option>`).join('')}</select></label><label class="field"><span>Find a character</span><input id="bank-search" value="${esc(bankSearch)}" placeholder="e.g. 看" lang="zh-Hant"></label></div><button class="pill" data-action="toggle-team-missed" aria-pressed="${bankMissed}">${bankMissed?'Showing missed sets':'Show missed sets'} · ${missed.size} items</button><p class="fine-print">${list.length} sets shown · 5 questions per set. Keys pending review remain unscored; listening items without exact audio offer a written preview.</p><div class="character-grid">${list.map(g=>`<button class="character-card" data-team-group="${g.id}"><span class="card-top">Source stage ${esc(g.level)}</span><span class="card-character" lang="zh-Hant">${esc(g.character)}</span><small>5 draft questions${g.questions.some(q=>missed.has(q.id))?' · revisit':''}</small></button>`).join('')}</div>${!list.length?'<div class="empty"><p>No matching sets. Try another filter.</p></div>':''}`,{active:'learn'});
}
function beginSelectedStage(){state.resume=null;save();const c=C.find(c=>c.level===state.start);if(c)openLesson(c.id,{restart:true});else go('stage/'+state.start);}
function render(){const[page,id]=route();if(page==='quiz'){if(!state.onboarded&&quiz?.type!=='diagnostic')return intro();quizPage();return;}if(!state.onboarded){if(page==='howto'||(state.howtoSeen&&state.name))return howto();return intro();}if(page==='profile')return profile();if(page==='progress')return progress();if(page==='review')return review();if(page==='team')return teamLibrary();if(page==='lesson')lesson(id);else if(page==='learn'||page==='explore'||page==='path')pathPage();else if(page==='stage'&&LEVELS.includes(id))stagePage(id);else home();}
function attachWritingPad(){const pad=$('.writing-pad');if(!pad)return;const ctx=pad.getContext('2d');ctx.lineWidth=5;ctx.lineCap='round';ctx.strokeStyle='#244b51';let drawing=false;pad.onpointerdown=e=>{drawing=true;pad.setPointerCapture(e.pointerId);const r=pad.getBoundingClientRect();ctx.beginPath();ctx.moveTo((e.clientX-r.left)*pad.width/r.width,(e.clientY-r.top)*pad.height/r.height);};pad.onpointermove=e=>{if(!drawing)return;const r=pad.getBoundingClientRect();ctx.lineTo((e.clientX-r.left)*pad.width/r.width,(e.clientY-r.top)*pad.height/r.height);ctx.stroke();};pad.onpointerup=()=>drawing=false;}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.audio){const item=audioItems.get(d.audio);if(item)player.play(item,state.preferences.speed);return;}
 if(d.pref){player.stop();state.preferences[d.pref]=d.value;save();render();settings();return;}
 if(d.teamGroup){startQuiz('team',d.teamGroup);return;}
 if(d.bank){bank=d.bank;teamLibrary();return;}
 if(d.mode){state.learningMode=d.mode;save();render();return;}
 if(d.filter){filter=d.filter;render();return;}
 if(d.stage){go('stage/'+d.stage);return;}
 if(d.lesson){openLesson(d.lesson);return;}
 if(d.matchWord){lessonSelectedWord=d.matchWord;lessonAnswer=null;render();return;}
 if(d.matchReading){if(!lessonSelectedWord){toast('Choose a word first, then choose its sound.');return;}const pairs=lessonPairOrder;const pair=pairs.find(([word])=>word===lessonSelectedWord);if(pair?.[1]===d.matchReading){lessonMatches[lessonSelectedWord]=d.matchReading;lessonAnswer='matched';lessonSelectedWord=null;}else lessonAnswer='try-again';render();return;}
 if(d.relearn){state.learningMode='explore';save();openLesson(d.relearn,{restart:true});return;}
 if(d.reviewId){startQuiz('review',d.reviewId);return;}if(d.lessonChoice){lessonAnswer=d.lessonChoice;render();return;}
 if(d.answer&&quiz&&!quiz.answered){const q=quiz.questions[quiz.index];if(q.rawText){if(q.listening&&!quiz.heard&&!quiz.previewed)return;submitDraft(d.answer);return;}quiz.chosen=d.answer;quiz.answered=true;if(d.answer===q.readingId)quiz.score++;if(quiz.type!=='diagnostic'){state=record(state,q,d.answer===q.readingId,quiz.type);save();}quizPage();return;}
 switch(d.action){
 case'check-voice':profile();$('#audio-setup').open=true;break;
 case'team-home':go('team');break;
 case'toggle-team-missed':bankMissed=!bankMissed;teamLibrary();break;
 case'preview-listening':quiz.previewed=true;draftQuizPage();break;
 case'show-draft-key':submitDraft(null,{preview:true});break;
 case'check-matching':{const q=quiz.questions[quiz.index];if(!q.pairs.every(p=>quiz.matchAnswers[p.id])){toast('Choose an answer for every match first.');break;}submitDraft(quiz.matchAnswers);break;}
 case'audio-setup':$('#settings').close();go('profile');setTimeout(()=>{const a=$('#audio-setup');if(a){a.open=true;a.scrollIntoView({block:'start'});}},50);break;
 case'settings':settings();break;
 case'close-settings':player.stop();$('#settings').close();break;
 case'howto':go('howto');break;
 case'begin-diagnostic':state.howtoSeen=true;save();startQuiz('diagnostic');break;
 case'accept-start':{const a=draftSummary(quiz.outcomes.slice(0,10)),b=draftSummary(quiz.outcomes.slice(10,20)),lvl=x=>x.unscored?state.start:x.correct/x.scored>=.8?'2':x.correct/x.scored>=.5?'1*':'1',suggested=lvl(a),chosen=$('#result-start')?.value;state.recommended=suggested;state.start=LEVELS.includes(chosen)?chosen:suggested;state.wordRecommended=lvl(b);state.onboarded=true;state.howtoSeen=true;state.learningMode='guided';save();quiz=null;go('path');break;}
 case'diagnostic':startQuiz('diagnostic');break;
 case'collection':go('learn');break;
 case'path':go('path');break;case'back-to-path':go('path');break;
 case'explore-stage':state.learningMode='explore';save();go('stage/'+d.level);break;
 case'next-card':player.stop();lessonIndex++;lessonAnswer=null;speechPrompted=false;render();$('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});attachWritingPad();break;
 case'previous-card':player.stop();lessonIndex=Math.max(0,lessonIndex-1);lessonAnswer=null;speechPrompted=false;render();window.scrollTo({top:0,behavior:'instant'});attachWritingPad();break;
 case'start-speaking':speechPrompted=true;render();$('.say-it-prompt')?.scrollIntoView({block:'center',behavior:'smooth'});break;
 case'spoken-practised':toast('Nice work. This tool does not record or grade your speech.');break;
 case'clear-writing':{const pad=$('.writing-pad');if(pad)pad.getContext('2d').clearRect(0,0,pad.width,pad.height);break;}
 case'restart-character':openLesson(d.id,{restart:true});break;
 case'next-character':openLesson(d.id,{restart:true});break;
 case'lesson-quiz':startQuiz('lesson',d.id);break;
 case'stage-quiz':startQuiz('stage',d.level);break;
 case'review-quiz':startQuiz('review');break;
 case'leave-session':if(route()[0]==='quiz'&&quiz&&!quiz.done){if(!confirm('Leave this check? Practice answers are saved, but an unfinished score will not count.'))break;quiz=null;}go('home');break;
 case'next-question':if(!quiz?.answered)break;player.stop();if(++quiz.index>=quiz.questions.length){quiz.done=true;if(quiz.type==='diagnostic'){state=recordStartingCheck(state,draftSummary(quiz.outcomes));save();}else if(quiz.type==='team'){state.teamHistory.push({groupId:quiz.id,...draftSummary(quiz.outcomes),at:Date.now()});save();}if(['lesson','stage'].includes(quiz.type)){state=finish(state,quiz.type,quiz.id,quiz.score,quiz.questions.length);save();}result();}else{quiz.answered=false;quiz.chosen=null;quiz.heard=false;quiz.previewed=false;quiz.matchAnswers={};quizPage();}window.scrollTo({top:0,behavior:'instant'});break;
 case'retry':startQuiz(quiz.type,quiz.id);break;
 case'result-home':go('home');break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='bank-search'){bankSearch=e.target.value;const pos=e.target.selectionStart;teamLibrary();$('#bank-search').focus();$('#bank-search').setSelectionRange(pos,pos);}if(e.target.id==='search'){search=e.target.value;const pos=e.target.selectionStart;collection();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{if(e.target.id==='welcome-form'){e.preventDefault();const name=$('#welcome-name').value.trim();if(!name)return;state.name=name;state.howtoSeen=false;save();go('howto');}if(e.target.id==='profile-form'){e.preventDefault();state.name=$('#learner-name').value.trim();save();profile();toast('Your nickname is saved.');}});
document.addEventListener('change',async e=>{if(e.target.dataset.match&&quiz)quiz.matchAnswers[e.target.dataset.match]=e.target.value;if(e.target.id==='bank-level'){bankLevel=e.target.value;teamLibrary();}});
$('#settings').addEventListener('close',()=>player.stop());
addEventListener('hashchange',()=>{player.stop();render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});attachWritingPad();});
addEventListener('pagehide',()=>player.stop());
document.addEventListener('visibilitychange',()=>{if(document.hidden)player.stop();});
render();
